    findFile(nameOrPredicate: string | ((entry: [path: string, file: ProjectFile]) => boolean)): ProjectFile | undefined;
    addFile(file: {
        path: string;
        content: string;
    }, options?: {
        resolveDependencies?: boolean;
        excludeFromCompiler?: boolean;
    }): ProjectFile;
